"use client"

import * as React from "react"
import { Toaster as ScrollsheetToaster, toast, useToasts } from "scrollsheet"

/**
 * scrollsheet's built-in toast system, mounted once near the app root.
 * Add `import "scrollsheet/toast.css"` next to your global styles (or use
 * the scrollsheet/auto entry). Fire from anywhere with toast(),
 * toast.success(), toast.promise() - https://scrollsheet.dev/docs/toasts
 */
function Toaster(props: React.ComponentProps<typeof ScrollsheetToaster>) {
  return <ScrollsheetToaster position="bottom-right" {...props} />
}

export { Toaster, toast, useToasts }
